"""Compile Aura's SM3 programs on Windows, or validate checked-in bytecode anywhere."""
import argparse
import ctypes
import hashlib
import os
from pathlib import Path
import re
import struct

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / 'Unibox/src/Features/Visuals/Aura/AuraShader.h'
OUTPUT = SOURCE.with_name('AuraBytecode.h')
MODES = 16


def source_text():
    return re.search(r'R"HLSL\((.*?)\)HLSL"', SOURCE.read_text(), re.S).group(1).encode()


def compile_windows(source, mode):
    if os.name != 'nt':
        raise RuntimeError('Regeneration needs Windows D3DCompiler 47; --check works on any OS.')
    class Macro(ctypes.Structure):
        _fields_ = [('name', ctypes.c_char_p), ('value', ctypes.c_char_p)]
    api = ctypes.WinDLL('d3dcompiler_47.dll').D3DCompile
    api.restype = ctypes.c_long
    api.argtypes = [ctypes.c_void_p, ctypes.c_size_t, ctypes.c_char_p, ctypes.c_void_p,
                    ctypes.c_void_p, ctypes.c_char_p, ctypes.c_char_p, ctypes.c_uint,
                    ctypes.c_uint, ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_void_p)]
    code, errors = ctypes.c_void_p(), ctypes.c_void_p()
    macros = (Macro * 2)(Macro(b'AURA_MODE', str(mode).encode()), Macro(None, None))
    buffer = ctypes.create_string_buffer(source)
    result = api(buffer, len(source), b'Aura.hlsl', macros, None, b'main', b'ps_3_0',
                 1 << 15, 0, ctypes.byref(code), ctypes.byref(errors))
    def contents(blob):
        table = ctypes.cast(blob, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
        address = ctypes.WINFUNCTYPE(ctypes.c_void_p, ctypes.c_void_p)(table[3])(blob)
        size = ctypes.WINFUNCTYPE(ctypes.c_size_t, ctypes.c_void_p)(table[4])(blob)
        return ctypes.string_at(address, size)
    def release(blob):
        if blob:
            table = ctypes.cast(blob, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
            ctypes.WINFUNCTYPE(ctypes.c_uint, ctypes.c_void_p)(table[2])(blob)
    try:
        if result < 0:
            raise RuntimeError(contents(errors).decode(errors='replace') if errors else f'HRESULT {result}')
        return contents(code)
    finally:
        release(code)
        release(errors)


def validate(data):
    if len(data) < 8 or len(data) % 4:
        raise ValueError('Invalid shader bytecode length')
    words = struct.unpack('<' + 'I' * (len(data) // 4), data)
    if words[0] != 0xFFFF0300 or words[-1] != 0x0000FFFF:
        raise ValueError('Expected a complete ps_3_0 program')
    return words


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--from-binaries', type=Path, help='Import shader-N.bin files from the same D3DCompile invocation')
    args = parser.parse_args()
    source = source_text()
    digest = hashlib.sha256(source).hexdigest()
    if args.check:
        header = OUTPUT.read_text()
        if f'SourceHash[] = "{digest}"' not in header:
            raise RuntimeError('Aura HLSL changed: regenerate AuraBytecode.h with this script on Windows.')
        for mode in range(MODES):
            array = re.search(rf'Mode{mode}\[\] = \{{(.*?)\}};', header, re.S).group(1)
            words = [int(value, 16) for value in re.findall(r'0x([0-9a-fA-F]+)', array)]
            validate(struct.pack('<' + 'I' * len(words), *words))
        print('Aura: source digest and all 16 embedded SM3 programs verified')
        return
    lines = ['#pragma once', '// Generated by .github/scripts/build-aura-shaders.py; do not edit.',
             '#include <cstddef>', '#include <cstdint>', 'namespace Aura::Shader', '{',
             f'inline constexpr char SourceHash[] = "{digest}";']
    for mode in range(MODES):
        data = ((args.from_binaries / f'shader-{mode}.bin').read_bytes() if args.from_binaries
                else compile_windows(source, mode))
        words = validate(data)
        lines.append(f'inline constexpr uint32_t Mode{mode}[] = {{')
        for i in range(0, len(words), 12):
            lines.append('    ' + ','.join(f'0x{word:08x}' for word in words[i:i + 12]) + ',')
        lines.append('};')
    lines.extend(['struct Program { const uint32_t* data; size_t bytes; };', 'inline constexpr Program Programs[] = {'])
    lines.extend(f'    {{Mode{mode},sizeof(Mode{mode})}},' for mode in range(MODES))
    lines.extend(['};', '}', ''])
    OUTPUT.write_text('\n'.join(lines))
    print(f'Generated {OUTPUT.name}: {MODES} programs')


if __name__ == '__main__':
    main()
